/// Resolves only the explicit co-presence entries in the shared registry.
pub fn parse_copresence(code: &str) -> Option<Refusal> {
    let reason = code.strip_prefix("copresence:")?;
    COPRESENCE_CODES
        .iter()
        .copied()
        .find(|known| known.reason() == reason)
}

/// Resolves only the explicit launcher entries in the shared registry.
pub fn parse_launcher(code: &str) -> Option<Refusal> {
    let reason = code.strip_prefix("launcher:")?;
    LAUNCHER_CODES
        .iter()
        .copied()
        .find(|known| known.reason() == reason)
}
